package terminal

import (
	"maps"
	"regexp"
	"slices"
	"strings"
	"unicode"

	"github.com/mrz1836/nilbox/internal/brand"
)

// The purposes a script's header names, completing "Generated by <name> …".
const (
	// PurposeSession is a launch script's purpose, and the header's default.
	PurposeSession = "to start a coding session"

	// PurposeFollowedRun is the purpose of a script whose run the app follows, and the
	// default of a script with a Recording.
	PurposeFollowedRun = "to run a command it follows"
)

// recordTool is the shell word that runs a recorded script's command: macOS's script(1),
// by its absolute path, so the user's PATH never picks another program.
const recordTool = "/usr/bin/script"

// envNamePattern is what an environment variable name must look like.
var envNamePattern = regexp.MustCompile(`^[A-Za-z_][A-Za-z0-9_]*$`)

// Script is what a launch script does: it changes into Dir, unsets the variables in
// Unset, sets those in Env, reads the prompt from PromptFile, and replaces itself with
// Binary, passing the prompt first and then Args, or Args and then the prompt when
// PromptLast is set. A NoPrompt script, which resumes a session, reads no prompt and
// passes Args alone. A script with a Recording runs Binary with Args under script(1)
// instead, recording the run for the app to follow, and reads no prompt.
type Script struct {
	// Purpose completes the header comment, "Generated by <name> <purpose>. Safe to
	// delete.", such as PurposeFollowedRun. Empty means PurposeSession, or
	// PurposeFollowedRun for a script with a Recording.
	Purpose string

	// Dir is the directory the session starts in.
	Dir string

	// Binary is the agent binary's absolute path.
	Binary string

	// Args are the agent's arguments besides the prompt, one argv element each.
	Args []string

	// PromptLast passes the prompt after Args rather than before them.
	PromptLast bool

	// Env holds the environment variables to set.
	Env map[string]string

	// Unset lists environment variables to remove.
	Unset []string

	// PromptFile holds the prompt text the script passes to the agent.
	PromptFile string

	// NoPrompt passes the agent no prompt, and PromptFile is not read.
	NoPrompt bool

	// Record, when set, runs Binary with Args under script(1) and records the run in its
	// files, rather than replacing the script with Binary.
	Record *Recording
}

// Recording is how a script records a run the app follows. The command runs under
// script(1), which gives it a pseudo-terminal (so colors and passphrase prompts work) and
// copies everything it writes into Log as it writes it. The shell that waits for it writes
// its own PID into PIDFile first, and the command's exit status into ExitFile once it
// ends, through a temporary file renamed into place, so ExitFile never holds half a status.
type Recording struct {
	// Log is the file the command's output is copied into.
	Log string

	// PIDFile receives the PID of the shell that waits for the command.
	PIDFile string

	// ExitFile receives the command's exit status. ExitFile + ".tmp" is written first.
	ExitFile string
}

// ScriptRenderer writes a Script as a file a terminal can run. A port to another shell
// family adds a renderer; callers never build command lines themselves.
type ScriptRenderer interface {
	// Render returns the script file's contents for s. A launch script reads the prompt
	// from s.PromptFile when it runs.
	Render(s Script) []byte

	// Extension is the script file's extension, including the dot.
	Extension() string
}

// ValidEnvName reports whether name can name an environment variable: a letter or an
// underscore, then letters, digits, and underscores.
func ValidEnvName(name string) bool {
	return envNamePattern.MatchString(name)
}

// POSIXRenderer renders scripts as POSIX sh. Every value is single-quoted, so no
// path, argument, or environment value is ever interpreted by the shell, and the prompt
// is read from its file rather than written into the script.
type POSIXRenderer struct{}

// DefaultRenderer returns the script renderer for launch files.
func DefaultRenderer() ScriptRenderer {
	return POSIXRenderer{}
}

// Extension returns ".command", which macOS terminals open and run directly.
func (POSIXRenderer) Extension() string { return ".command" }

// Render returns a script that changes into s.Dir, adjusts the environment, reads the
// prompt file, and replaces itself with the agent:
//
//	#!/bin/sh
//	# Generated by <name> to start a coding session. Safe to delete.
//	set -eu
//	cd -- '<dir>' || exit 1
//	unset NAME
//	export NAME='value'
//	prompt=$(cat -- '<prompt file>')
//	exec '<agent>' "$prompt" '<arg>' ...
//
// or, with PromptLast, exec '<agent>' '<arg>' ... "$prompt", and with NoPrompt, no
// prompt line and exec '<agent>' '<arg>' ....
//
// With a Recording, the script runs the command under script(1) and records the run:
//
//	#!/bin/sh
//	# Generated by <name> to run a command it follows. Safe to delete.
//	set -u
//	finish() {
//	  printf '%s\n' "$1" > '<exit file>.tmp' && mv '<exit file>.tmp' '<exit file>'
//	  exit "$1"
//	}
//	printf '%s\n' "$$" > '<pid file>'
//	cd -- '<dir>' || finish 1
//	unset NAME
//	export NAME='value'
//	/usr/bin/script -q -F '<log>' '<binary>' '<arg>' ...
//	finish "$?"
//
// The shell's PID is recorded first, so the app follows the run from its first line, and
// every way the script ends records an exit status: it runs without set -e, so a failing
// command still has its status recorded, and a folder it can't change into, or an
// invalid variable name (which no caller passes), is followed by || finish 1 instead.
func (POSIXRenderer) Render(s Script) []byte {
	return renderPOSIX(s, recordTool)
}

// renderPOSIX is Render with tool, the shell word that runs a recorded command, given;
// tests pass a stand-in for script(1).
func renderPOSIX(s Script, tool string) []byte {
	var b strings.Builder

	b.WriteString("#!/bin/sh\n")
	b.WriteString("# Generated by " + brand.Name + " " + oneLine(s.purpose()) + ". Safe to delete.\n")

	if s.Record != nil {
		b.WriteString("set -u\n")
		writeRecordStart(&b, s.Record)
		b.WriteString("cd -- " + shQuote(s.Dir) + " || finish 1\n")
	} else {
		b.WriteString("set -eu\n")
		b.WriteString("cd -- " + shQuote(s.Dir) + " || exit 1\n")
	}

	for _, name := range s.Unset {
		b.WriteString("unset " + shName(name) + s.orStop(name) + "\n")
	}

	for _, name := range slices.Sorted(maps.Keys(s.Env)) {
		b.WriteString("export " + shName(name) + "=" + shQuote(s.Env[name]) + s.orStop(name) + "\n")
	}

	if s.Record != nil {
		writeRecorded(&b, s, tool)
	} else {
		writeExec(&b, s)
	}

	return []byte(b.String())
}

// purpose is what the script's header says it is for.
func (s Script) purpose() string {
	switch {
	case s.Purpose != "":
		return s.Purpose
	case s.Record != nil:
		return PurposeFollowedRun
	default:
		return PurposeSession
	}
}

// orStop returns what follows the line that unsets or sets name: nothing, or, for an
// invalid name in a recorded script, which runs without set -e, " || finish 1", so the
// shell stops there, with its status recorded, as a launch script's set -e makes it.
func (s Script) orStop(name string) string {
	if s.Record == nil || ValidEnvName(name) {
		return ""
	}

	return " || finish 1"
}

// writeExec writes a launch script's last lines: the prompt read from its file, unless
// NoPrompt, and the exec of the agent with its arguments.
func writeExec(b *strings.Builder, s Script) {
	if !s.NoPrompt {
		b.WriteString("prompt=$(cat -- " + shQuote(s.PromptFile) + ")\n")
	}

	b.WriteString("exec " + shQuote(s.Binary))

	if !s.NoPrompt && !s.PromptLast {
		b.WriteString(` "$prompt"`)
	}

	writeArgs(b, s.Args)

	if !s.NoPrompt && s.PromptLast {
		b.WriteString(` "$prompt"`)
	}

	b.WriteString("\n")
}

// writeRecordStart writes a recorded script's first lines: finish, which records an exit
// status, written to a temporary file and renamed into place, and exits with it; then the
// waiting shell's PID.
func writeRecordStart(b *strings.Builder, r *Recording) {
	tmp := shQuote(r.ExitFile + ".tmp")

	b.WriteString("finish() {\n")
	b.WriteString(`  printf '%s\n' "$1" > ` + tmp + " && mv " + tmp + " " + shQuote(r.ExitFile) + "\n")
	b.WriteString(`  exit "$1"` + "\n")
	b.WriteString("}\n")
	b.WriteString(`printf '%s\n' "$$" > ` + shQuote(r.PIDFile) + "\n")
}

// writeRecorded writes a recorded script's last lines: the command run by tool with its
// output copied to the log, and its exit status recorded.
func writeRecorded(b *strings.Builder, s Script, tool string) {
	b.WriteString(tool + " -q -F " + shQuote(s.Record.Log) + " " + shQuote(s.Binary))
	writeArgs(b, s.Args)
	b.WriteString("\n")
	b.WriteString(`finish "$?"` + "\n")
}

// writeArgs writes each argument, quoted, after a space.
func writeArgs(b *strings.Builder, args []string) {
	for _, arg := range args {
		b.WriteString(" " + shQuote(arg))
	}
}

// oneLine replaces every control character in s, a newline above all, with a space, so
// text written into a comment line stays in it.
func oneLine(s string) string {
	return strings.Map(func(r rune) rune {
		if unicode.IsControl(r) {
			return ' '
		}

		return r
	}, s)
}

// shName returns an environment variable name as the script writes it. A valid name is
// written as is. Anything else (which a launch plan never holds) is quoted, so the shell
// rejects it as an invalid identifier and the script stops instead of running it.
func shName(name string) string {
	if ValidEnvName(name) {
		return name
	}

	return shQuote(name)
}

// shQuote quotes s for a POSIX shell. It is wrapped in single quotes, inside which
// nothing is special, and each single quote inside it closes the quoting, adds an
// escaped quote, and reopens the quoting.
func shQuote(s string) string {
	return "'" + strings.ReplaceAll(s, "'", `'\''`) + "'"
}
